class Solution:
    def countValidPrefixes(self, s: str) -> int:
        z = o = ans = 0
        for c in s:
            if c == '0':
                z += 1
            else:
                o += 1
            if abs(z - o) <= 1:
                ans += 1
        return ans

c.cpp:
class Solution {
public:
    int countValidPrefixes(string s) {
        int z = 0, o = 0, ans = 0;
        for (char c : s) {
            if (c == '0') z++; else o++;
            if (abs(z - o) <= 1) ans++;
        }
        return ans;
    }
};

c.java:
class Solution {
    public int countValidPrefixes(String s) {
        int z = 0, o = 0, ans = 0;
        for (char c : s.toCharArray()) {
            if (c == '0') z++; else o++;
            if (Math.abs(z - o) <= 1) ans++;
        }
        return ans;
    }
}

